mapper.select:
select *
from t_feedback


        AND (
        STRPOS(feedback_content,#{query.searchWord}) > 0
        OR STRPOS(user_name,#{query.searchWord}) > 0
        )


        AND CAST(create_time AS DATE) >= #{query.startDate}


        AND CAST(create_time AS DATE) <= #{query.endDate}



    order by create_time desc
